// دمج قواعد SAMA مع مخرجات Agent 1
const agent1Data = $('Agent 1 - استخراج المحتوى').first().json.output || {};
const samaRules = $input.all().map(item => item.json);

const rulesText = samaRules.map((rule, idx) => {
  const textAr = rule.description_ar || '';
  const textEn = rule.description || '';
  const ruleText = textAr || textEn;
  return `(${idx + 1}) [خطورة: ${rule.severity ?? 'غير محدد'} | تأثير الدرجة: ${rule.compliance_score_impact ?? 0}] ${ruleText} — نوع المخالفة: ${rule.violation_type || ''} | الفئة: ${rule.category || ''} | المصدر: ${rule.source_file || 'SAMA'} | المعرّف: ${rule.id || ''}`;
}).join('\n');

return [{
  json: {
    claims: agent1Data.detected_claims || [],
    claims_text: JSON.stringify(agent1Data.detected_claims || [], null, 2),
    extracted_figures: agent1Data.extracted_figures || {},
    figures_text: JSON.stringify(agent1Data.extracted_figures || {}, null, 2),
    disclosures_present: agent1Data.disclosures_present || [],
    disclosures_text: JSON.stringify(agent1Data.disclosures_present || [], null, 2),
    ad_summary: agent1Data.ad_summary || '',
    product_type: agent1Data.product_type || 'غير محدد',
    original_ad: $('Input Parser').first().json.ad_text,
    rules_text: rulesText || 'لا توجد قواعد مطابقة في قاعدة البيانات.',
    rules_count: samaRules.length
  }
}];

