const a2 = $('Agent 2 - الامتثال ومطابقة القواعد').first().json.output || {};
const rawFindings = a2.findings || [];

// إزالة المخالفات المكررة (حتمي) بناءً على violation_id + claim_text
const seen = new Set();
const findings = [];
for (const f of rawFindings) {
  const key = `${(f.violation_id || '').trim()}|${(f.claim_text || '').trim()}`;
  if (seen.has(key)) continue;
  seen.add(key);
  findings.push(f);
}

return [{
  json: {
    original_ad: $('Prepare Rules Context').first().json.original_ad,
    findings,
    overall_compliance: a2.overall_compliance || ''
  }
}];

