const a3 = $('Agent 3 - الصياغة البديلة').first().json.output || {};
const ctx = $('Prepare Rules Context').first().json;
const a2 = $('Agent 2 - الامتثال ومطابقة القواعد').first().json.output || {};

// استخدم قائمة المخالفات المنقّاة (بعد إزالة التكرار) من Prepare Rewrite Context
const findings = $('Prepare Rewrite Context').first().json.findings || [];
// حساب حتمي (deterministic) للدرجة من المخالفات المنقّاة
const totalImpact = findings.reduce((sum, f) => sum + (Number(f.score_impact) || 0), 0);
const computedScore = Math.max(0, Math.min(100, 100 - totalImpact));

let computedStatus;
if (findings.length === 0) {
  computedStatus = 'منخفض';
} else if (computedScore >= 70) {
  computedStatus = 'يحتاج مراجعة';
} else {
  computedStatus = 'عالي المخاطر';
}

return [{
  json: {
    ad_summary: ctx.ad_summary,
    product_type: ctx.product_type,
    findings,
    findings_text: JSON.stringify(findings, null, 2),
    total_score_impact: totalImpact,
    computed_score: computedScore,
    computed_status: computedStatus,
    violations_count: findings.length,
    overall_compliance: a2.overall_compliance || '',
    suggested_rewrite: a3.suggested_rewrite || '',
    changes_explained: a3.changes_explained || []
  }
}];

