const f = $('Agent 4 - الدرجة والتقرير النهائي').first().json.output || {};
const ctx = $('Prepare Report Context').first().json;
const originalAd = $('Prepare Rules Context').first().json.original_ad || '';

const score = f.readiness_score ?? 0;
const status = f.status || 'غير محدد';
const findings = f.findings || [];
const recommendations = f.recommendations || [];
const rewrite = f.suggested_rewrite || '';
const summary = f.summary || '';
const productType = ctx.product_type || '';
const generatedAt = new Date().toLocaleString('ar-SA', { timeZone: 'Asia/Riyadh' });

// لون الحالة
let statusColor = '#3E7C68';
if (status.includes('عالي')) statusColor = '#C0463A';
else if (status.includes('مراجعة')) statusColor = '#B07B4F';

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const riskBadge = (r) => {
  let c = '#3E7C68';
  if (r === 'عالي') c = '#C0463A';
  else if (r === 'متوسط') c = '#B07B4F';
  return `<span style="background:${c};color:#fff;padding:2px 10px;border-radius:12px;font-size:12px;white-space:nowrap">${esc(r)}</span>`;
};

const findingsRows = findings.map((x, i) => `
  <tr>
    <td style="text-align:center">${i + 1}</td>
    <td>${esc(x.claim_text)}</td>
    <td style="text-align:center">${riskBadge(x.risk_level)}</td>
    <td>${esc(x.rule_reference)}</td>
    <td style="text-align:center;font-family:monospace;font-size:11px">${esc(x.violation_id || '')}</td>
    <td style="text-align:center">${esc(x.rule_source || '')}</td>
    <td style="text-align:center">${esc(x.confidence || '')}</td>
  </tr>`).join('');

const recsList = recommendations.map((r) => `<li>${esc(r)}</li>`).join('');

const html = `<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<style>
  * { box-sizing: border-box; }
  body { font-family: 'Tahoma','Arial',sans-serif; margin:0; padding:32px; color:#1B2A4A; line-height:1.7; direction:rtl; }
  .header { display:flex; justify-content:space-between; align-items:center; border-bottom:3px solid #1B2A4A; padding-bottom:16px; margin-bottom:24px; }
  .brand { font-size:28px; font-weight:bold; color:#1B2A4A; }
  .brand small { display:block; font-size:13px; color:#6B7392; font-weight:normal; margin-top:4px; }
  .meta { text-align:left; font-size:12px; color:#6B7392; }
  .score-card { display:flex; gap:16px; margin-bottom:24px; }
  .score-box { flex:1; border:1px solid #E3E6F0; border-radius:12px; padding:20px; text-align:center; }
  .score-num { font-size:44px; font-weight:bold; }
  .score-label { font-size:13px; color:#6B7392; margin-top:4px; }
  .status-pill { display:inline-block; color:#fff; padding:8px 20px; border-radius:20px; font-size:18px; font-weight:bold; }
  h2 { color:#1B2A4A; font-size:18px; border-right:4px solid #1B2A4A; padding-right:10px; margin-top:28px; }
  .summary { background:#F5F6FA; border:1px solid #A89AD4; border-radius:10px; padding:16px; }
  table { width:100%; border-collapse:collapse; margin-top:12px; font-size:13px; }
  th { background:#1B2A4A; color:#fff; padding:10px 8px; text-align:right; }
  td { border:1px solid #E3E6F0; padding:8px; vertical-align:top; }
  tr:nth-child(even) td { background:#f9fafb; }
  .ba { display:flex; gap:16px; margin-top:12px; }
  .ba-box { flex:1; border-radius:10px; padding:16px; }
  .before { background:#FBEDEB; border:1px solid #F4C4BD; }
  .after { background:#EAF2EF; border:1px solid #B7D8CD; }
  .ba-title { font-weight:bold; margin-bottom:8px; }
  ul { padding-right:20px; }
  .footer { margin-top:40px; border-top:1px solid #E3E6F0; padding-top:12px; font-size:11px; color:#9ca3af; text-align:center; }
</style>
</head>
<body>
  <div class="header">
    <div class="brand">مُعتَمَد<small>منصة فحص امتثال الإعلانات المالية — قواعد SAMA</small></div>
    <div class="meta">تاريخ التقرير: ${esc(generatedAt)}<br>نوع المنتج: ${esc(productType)}<br>عدد المخالفات: ${findings.length}</div>
  </div>

  <div class="score-card">
    <div class="score-box">
      <div class="score-num" style="color:${statusColor}">${esc(score)}</div>
      <div class="score-label">درجة الجاهزية (من 100)</div>
    </div>
    <div class="score-box" style="display:flex;flex-direction:column;justify-content:center">
      <div><span class="status-pill" style="background:${statusColor}">${esc(status)}</span></div>
      <div class="score-label">الحالة التنظيمية</div>
    </div>
  </div>

  <h2>الملخص التنفيذي</h2>
  <div class="summary">${esc(summary)}</div>

  <h2>المخالفات المرصودة ومراجعها النظامية</h2>
  ${findings.length ? `<table>
    <thead><tr>
      <th style="width:30px">#</th><th>العبارة / البند</th><th>الخطورة</th>
      <th>القاعدة النظامية</th><th>المعرّف</th><th>المصدر</th><th>الثقة</th>
    </tr></thead>
    <tbody>${findingsRows}</tbody>
  </table>` : '<p>لا توجد مخالفات مرصودة. الإعلان متوافق.</p>'}

  <h2>المقارنة: قبل / بعد</h2>
  <div class="ba">
    <div class="ba-box before"><div class="ba-title">الإعلان الأصلي (قبل)</div>${esc(originalAd)}</div>
    <div class="ba-box after"><div class="ba-title">الصياغة المقترحة المتوافقة (بعد)</div>${esc(rewrite)}</div>
  </div>

  <h2>التوصيات</h2>
  <ul>${recsList || '<li>لا توجد توصيات.</li>'}</ul>

  <div class="footer">تم إنشاء هذا التقرير آلياً بواسطة نظام مُعتَمَد متعدد الوكلاء (Multi-Agent) — استناداً إلى قواعد البنك المركزي السعودي (SAMA). هذا التقرير استرشادي ولا يُغني عن المراجعة البشرية النهائية.</div>
</body>
</html>`;

return [{ json: { report_html: html, final_output: f, generated_at: new Date().toISOString() } }];

const final = $('Agent 4 - الدرجة والتقرير النهائي').first().json.output || {};
const reportHtml = $('Build Report HTML').first().json.report_html || '';

// تم تحويل التقرير إلى ملف HTML (binary) عبر عقدة Convert to File
const binary = $input.first().binary || {};
const fileEntry = binary.data || {};
const fileName = fileEntry.fileName || 'mutamad-report.html';
const reportReady = !!fileEntry.data;

return [{
  binary,
  json: {
    final_output: final,
    report: {
      report_ready: reportReady,
      report_filename: fileName,
      report_format: 'html',
      report_html: reportHtml
    },
    generated_at: new Date().toISOString()
  }
}];
